import AppKit
import CoreImage

// A CleanShot window capture is ~1:1; APP_DESKTOP wants 16:10. Pad rather than
// stretch: the backdrop is the same frame blown up and blurred, so the wallpaper
// gradient continues past the window instead of meeting a flat bar.
let W = 2880, H = 1800

let args = CommandLine.arguments
guard args.count == 3 else { FileHandle.standardError.write(Data("usage: compose <in> <out>\n".utf8)); exit(2) }

guard let image = NSImage(contentsOf: URL(fileURLWithPath: args[1])),
      let source = image.cgImage(forProposedRect: nil, context: nil, hints: nil)
else { FileHandle.standardError.write(Data("cannot read \(args[1])\n".utf8)); exit(3) }

guard let context = CGContext(
    data: nil, width: W, height: H, bitsPerComponent: 8, bytesPerRow: 0,
    space: CGColorSpace(name: CGColorSpace.sRGB)!,
    bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue
) else { exit(4) }

let ci = CIImage(cgImage: source)
let cover = max(CGFloat(W) / CGFloat(source.width), CGFloat(H) / CGFloat(source.height)) * 1.25
let enlarged = ci.transformed(by: CGAffineTransform(scaleX: cover, y: cover))
// Gaussian blur bleeds past the extent and leaves a soft edge; inset past it.
let blurred = enlarged.applyingGaussianBlur(sigma: 60).cropped(to: enlarged.extent.insetBy(dx: 180, dy: 180))
if let backdrop = CIContext().createCGImage(blurred, from: blurred.extent) {
    let w = CGFloat(backdrop.width), h = CGFloat(backdrop.height)
    context.draw(backdrop, in: CGRect(x: (CGFloat(W) - w) / 2, y: (CGFloat(H) - h) / 2, width: w, height: h))
}

let height = CGFloat(H) * 0.90
let scale = height / CGFloat(source.height)
let width = CGFloat(source.width) * scale
context.interpolationQuality = .high
context.draw(source, in: CGRect(x: (CGFloat(W) - width) / 2, y: (CGFloat(H) - height) / 2, width: width, height: height))

guard let output = context.makeImage(),
      let png = NSBitmapImageRep(cgImage: output).representation(using: .png, properties: [:])
else { exit(5) }
try png.write(to: URL(fileURLWithPath: args[2]))

import AppKit

// A CleanShot window capture is ~1:1; APP_DESKTOP wants 16:10. Scale the capture
// to full height, then extend the wallpaper sideways with a mirrored copy of its
// own edge — a smooth gradient meets its reflection with no seam, where a flat
// pad or a second blurred layer both show one.
let W = 2880, H = 1800

let args = CommandLine.arguments
guard args.count == 3 else { FileHandle.standardError.write(Data("usage: compose <in> <out>\n".utf8)); exit(2) }

guard let image = NSImage(contentsOf: URL(fileURLWithPath: args[1])),
      let source = image.cgImage(forProposedRect: nil, context: nil, hints: nil)
else { FileHandle.standardError.write(Data("cannot read \(args[1])\n".utf8)); exit(3) }

guard let context = CGContext(
    data: nil, width: W, height: H, bitsPerComponent: 8, bytesPerRow: 0,
    space: CGColorSpace(name: CGColorSpace.sRGB)!,
    bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue
) else { exit(4) }
context.interpolationQuality = .high

let scale = CGFloat(H) / CGFloat(source.height)
let width = (CGFloat(source.width) * scale).rounded()
let originX = ((CGFloat(W) - width) / 2).rounded()

// The mirrored wings, drawn first so the capture's own edge lands on top of them.
let wing = originX
let sliceWidth = Int((wing / scale).rounded())
if sliceWidth > 0 {
    if let left = source.cropping(to: CGRect(x: 0, y: 0, width: sliceWidth, height: source.height)) {
        context.saveGState()
        context.translateBy(x: originX, y: 0)
        context.scaleBy(x: -1, y: 1)
        context.draw(left, in: CGRect(x: 0, y: 0, width: wing, height: CGFloat(H)))
        context.restoreGState()
    }
    if let right = source.cropping(to: CGRect(
        x: source.width - sliceWidth, y: 0, width: sliceWidth, height: source.height
    )) {
        context.saveGState()
        context.translateBy(x: originX + width + wing, y: 0)
        context.scaleBy(x: -1, y: 1)
        context.draw(right, in: CGRect(x: 0, y: 0, width: wing, height: CGFloat(H)))
        context.restoreGState()
    }
}

context.draw(source, in: CGRect(x: originX, y: 0, width: width, height: CGFloat(H)))

guard let output = context.makeImage(),
      let png = NSBitmapImageRep(cgImage: output).representation(using: .png, properties: [:])
else { exit(5) }
try png.write(to: URL(fileURLWithPath: args[2]))

import AppKit
import CoreImage

// A CleanShot window capture is ~1:1; APP_DESKTOP wants 16:10. Scale the capture
// to full height, then extend it sideways from a narrow strip of its own margin —
// stretched and blurred, so the wallpaper gradient carries on past the frame with
// no structure to give the join away. The strip must stay inside the margin: a
// wider one catches the window and mirrors half a sidebar into the wing.
let W = 2880, H = 1800
let stripWidth = 120

let args = CommandLine.arguments
guard args.count == 3 else { FileHandle.standardError.write(Data("usage: compose <in> <out>\n".utf8)); exit(2) }

guard let image = NSImage(contentsOf: URL(fileURLWithPath: args[1])),
      let source = image.cgImage(forProposedRect: nil, context: nil, hints: nil)
else { FileHandle.standardError.write(Data("cannot read \(args[1])\n".utf8)); exit(3) }

guard let context = CGContext(
    data: nil, width: W, height: H, bitsPerComponent: 8, bytesPerRow: 0,
    space: CGColorSpace(name: CGColorSpace.sRGB)!,
    bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue
) else { exit(4) }
context.interpolationQuality = .high

let scale = CGFloat(H) / CGFloat(source.height)
let width = (CGFloat(source.width) * scale).rounded()
let originX = ((CGFloat(W) - width) / 2).rounded()
let ciContext = CIContext()

func wing(from strip: CGImage, width wingWidth: CGFloat) -> CGImage? {
    let ci = CIImage(cgImage: strip)
    let stretched = ci.transformed(by: CGAffineTransform(
        scaleX: wingWidth / CGFloat(strip.width), y: CGFloat(H) / CGFloat(strip.height)
    ))
    // Clamp first: a blur over a bounded extent darkens its own edges.
    let soft = stretched.clampedToExtent().applyingGaussianBlur(sigma: 30)
    return ciContext.createCGImage(soft, from: CGRect(x: 0, y: 0, width: wingWidth, height: CGFloat(H)))
}

if originX > 0 {
    if let strip = source.cropping(to: CGRect(x: 0, y: 0, width: stripWidth, height: source.height)),
       let left = wing(from: strip, width: originX) {
        context.draw(left, in: CGRect(x: 0, y: 0, width: originX, height: CGFloat(H)))
    }
    if let strip = source.cropping(to: CGRect(
        x: source.width - stripWidth, y: 0, width: stripWidth, height: source.height
    )), let right = wing(from: strip, width: originX) {
        context.draw(right, in: CGRect(x: originX + width, y: 0, width: originX, height: CGFloat(H)))
    }
}

context.draw(source, in: CGRect(x: originX, y: 0, width: width, height: CGFloat(H)))

guard let output = context.makeImage(),
      let png = NSBitmapImageRep(cgImage: output).representation(using: .png, properties: [:])
else { exit(5) }
try png.write(to: URL(fileURLWithPath: args[2]))

import AppKit
import CoreImage

// Blur named rectangles of an image. Rects arrive as x,y,w,h in pixels with the
// origin at the TOP left, the way a reader measures them off the picture;
// CGContext draws from the bottom, so each is flipped on the way in.
let args = CommandLine.arguments
guard args.count >= 4 else {
    FileHandle.standardError.write(Data("usage: redact <in> <out> x,y,w,h [x,y,w,h ...]\n".utf8))
    exit(2)
}

guard let image = NSImage(contentsOf: URL(fileURLWithPath: args[1])),
      let source = image.cgImage(forProposedRect: nil, context: nil, hints: nil)
else { FileHandle.standardError.write(Data("cannot read \(args[1])\n".utf8)); exit(3) }

let W = source.width, H = source.height
guard let context = CGContext(
    data: nil, width: W, height: H, bitsPerComponent: 8, bytesPerRow: 0,
    space: CGColorSpace(name: CGColorSpace.sRGB)!,
    bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue
) else { exit(4) }
context.interpolationQuality = .high
context.draw(source, in: CGRect(x: 0, y: 0, width: W, height: H))

let ciContext = CIContext()
for spec in args.dropFirst(3) {
    let n = spec.split(separator: ",").compactMap { Int($0) }
    guard n.count == 4 else { FileHandle.standardError.write(Data("bad rect \(spec)\n".utf8)); exit(5) }
    let (x, yTop, w, h) = (n[0], n[1], n[2], n[3])
    guard let patch = source.cropping(to: CGRect(x: x, y: yTop, width: w, height: h)) else { continue }

    let ci = CIImage(cgImage: patch)
    // Pixellate first so glyph strokes are gone even where the blur has little
    // room to work, then blur the blocks so the result does not read as censored.
    let blocked = ci.clampedToExtent()
        .applyingFilter("CIPixellate", parameters: [kCIInputScaleKey: max(h / 3, 8)])
        .applyingGaussianBlur(sigma: Double(h) / 3)
    guard let soft = ciContext.createCGImage(blocked, from: ci.extent) else { continue }
    context.draw(soft, in: CGRect(x: x, y: H - yTop - h, width: w, height: h))
}

guard let output = context.makeImage(),
      let png = NSBitmapImageRep(cgImage: output).representation(using: .png, properties: [:])
else { exit(6) }
try png.write(to: URL(fileURLWithPath: args[2]))
